const updateVote = `-- name: UpdateVote :exec
UPDATE votes SET value = $1, ap_id = $2
WHERE actor_id = $3 AND post_id IS NOT DISTINCT FROM $4 AND comment_id IS NOT DISTINCT FROM $5
`

type UpdateVoteParams struct {
	Value     int16
	ApID      *string
	ActorID   int64
	PostID    *int64
	CommentID *int64
}

func (q *Queries) UpdateVote(ctx context.Context, arg UpdateVoteParams) error {
	_, err := q.db.Exec(ctx, updateVote,
		arg.Value,
		arg.ApID,
		arg.ActorID,
		arg.PostID,
		arg.CommentID,
	)
	return err
}

const voteByApID = `-- name: VoteByApID :one
SELECT actor_id, post_id, comment_id, value, counted, ap_id, created_at FROM votes WHERE ap_id = $1
`

func (q *Queries) VoteByApID(ctx context.Context, apID *string) (Vote, error) {
	row := q.db.QueryRow(ctx, voteByApID, apID)
	var i Vote
	err := row.Scan(
		&i.ActorID,
		&i.PostID,
		&i.CommentID,
		&i.Value,
		&i.Counted,
		&i.ApID,
		&i.CreatedAt,
	)
	return i, err
}
